// Validate the incoming query and clamp topK.
//
// The namespace comes from the app, which derives it from the signed-in student's own
// id - this workflow never chooses it.

const body = $input.first().json.body ?? $input.first().json;
const { namespace, question } = body;

if (!namespace || typeof question !== 'string' || !question.trim()) {
  throw new Error('payload must include namespace and a non-empty question');
}

const topK = Math.min(Math.max(Number(body.topK) || 8, 1), 30);

return [{ json: { namespace, question: question.trim().slice(0, 4000), topK } }];

// Return ids and scores only - deliberately not the text.
//
// The app hydrates chunk text from Postgres under the student's own session, so RLS
// decides what can reach the prompt. Passing text back from here would route around
// that. Do not add chunk_text to this response.

const hits = $input.first().json?.result?.hits ?? [];

return [{
  json: {
    matches: hits.map((h) => ({
      chunkId: h._id,
      score: h._score,
    })),
  },
}];
